(()=>{const select=$('#particle-renderer'),label=document.createElement('label');label.id='bolt-branches-label';label.innerHTML='Lightning branches<input id="bolt-branches" type="number" min="0" max="8" step="1" value="0"><small>Branches stay inside the same sideways distance limit. Speed controls growth; lifetime controls maximum reach. Enable Collide with a surface to stop on impact.</small>';select.closest('label').after(label);$('#bolt-branches').onchange=e=>{const v=Number(e.target.value);if(!Number.isInteger(v)||v<0||v>8){e.target.value=state.boltBranches||0;return;}state.boltBranches=v;persist();};
const previous=sync;sync=()=>{previous();const bolt=state.renderer==='lightning';label.hidden=!bolt;$('#advanced-motion').disabled=bolt;$('#bolt-branches').value=state.boltBranches||0;const spread=document.querySelector('[data-key="spread"]');if(spread){spread.closest('label').querySelector('.label-row span').textContent=bolt?'Zigzags (Spread)':'Spread';if(bolt){const update=()=>$('#value-spread').textContent=Math.round(2+(state.spread-5)/95*30)+' bends';const input=spread.oninput;spread.oninput=e=>{input(e);update();};update();}}const radius=$('#advanced-radiusVariation').closest('label');radius.firstChild.textContent=bolt?'Maximum left / right distance (cm)':'Distance from center variation (%)';};const change=select.onchange;select.onchange=async e=>{await change(e);if(state.renderer==='lightning'){state.motion='aimed';state.simulation='cpu';persist();}restart();sync();};sync();})();
